package realestate.dao;
import realestate.model.*;import realestate.util.*;import java.sql.*;import java.math.BigDecimal;import java.util.*;
public class PropertyDAO {
 private Property map(ResultSet r)throws SQLException{long id=r.getLong("property_id"),sid=r.getLong("seller_id");String type=r.getString("property_type"),t=r.getString("title"),l=r.getString("location"),d=r.getString("description"),st=r.getString("status");BigDecimal price=r.getBigDecimal("price");int b=r.getInt("bedrooms"),ba=r.getInt("bathrooms");double a=r.getDouble("area");return switch(type){case "HOUSE"->new House(id,sid,t,l,price,b,ba,a,d,st);case "APARTMENT"->new Apartment(id,sid,t,l,price,b,ba,a,d,st);case "LAND"->new Land(id,sid,t,l,price,b,ba,a,d,st);default->new CommercialProperty(id,sid,t,l,price,b,ba,a,d,st);};}
 private List<Property> query(String sql, Binder binder)throws SQLException{List<Property> out=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){binder.bind(p);try(ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}}return out;} private interface Binder{void bind(PreparedStatement p)throws SQLException;}
 public List<Property> browse()throws SQLException{return query("SELECT * FROM properties WHERE status='AVAILABLE' ORDER BY property_id DESC",p->{});}
 public List<Property> mine(long seller)throws SQLException{return query("SELECT * FROM properties WHERE seller_id=? ORDER BY property_id DESC",p->p.setLong(1,seller));}
 public List<Property> all()throws SQLException{return query("SELECT * FROM properties ORDER BY property_id DESC",p->{});}
 public List<Property> search(String location,String type,BigDecimal max,int beds)throws SQLException{return query("SELECT * FROM properties WHERE status='AVAILABLE' AND (?='' OR LOWER(location) LIKE ?) AND (?='ALL' OR property_type=?) AND (? IS NULL OR price<=?) AND (?<0 OR bedrooms>=?) ORDER BY property_id DESC",p->{p.setString(1,location);p.setString(2,"%"+location.toLowerCase()+"%");p.setString(3,type);p.setString(4,type);if(max==null){p.setNull(5,Types.DECIMAL);p.setNull(6,Types.DECIMAL);}else{p.setBigDecimal(5,max);p.setBigDecimal(6,max);}p.setInt(7,beds);p.setInt(8,beds);});}
 public long add(Property x)throws SQLException{String sql="INSERT INTO properties(seller_id,title,property_type,location,price,bedrooms,bathrooms,area,description,status) VALUES(?,?,?,?,?,?,?,?,?,'AVAILABLE')";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){fill(p,x);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 private void fill(PreparedStatement p,Property x)throws SQLException{p.setLong(1,x.getSellerId());p.setString(2,x.getTitle());p.setString(3,x.getType());p.setString(4,x.getLocation());p.setBigDecimal(5,x.getPrice());p.setInt(6,x.getBedrooms());p.setInt(7,x.getBathrooms());p.setDouble(8,x.getArea());p.setString(9,x.getDescription());}
 public boolean update(Property x,long actor,boolean admin)throws SQLException{String sql="UPDATE properties SET title=?,location=?,price=?,bedrooms=?,bathrooms=?,area=?,description=?,updated_at=SYSUTCDATETIME() WHERE property_id=? AND (?=1 OR seller_id=?)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,x.getTitle());p.setString(2,x.getLocation());p.setBigDecimal(3,x.getPrice());p.setInt(4,x.getBedrooms());p.setInt(5,x.getBathrooms());p.setDouble(6,x.getArea());p.setString(7,x.getDescription());p.setLong(8,x.getId());p.setBoolean(9,admin);p.setLong(10,actor);return p.executeUpdate()>0;}}
 public boolean deactivate(long id,long actor,boolean admin)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE properties SET status='INACTIVE',updated_at=SYSUTCDATETIME() WHERE property_id=? AND (?=1 OR seller_id=?)")){p.setLong(1,id);p.setBoolean(2,admin);p.setLong(3,actor);return p.executeUpdate()>0;}}
 public boolean existsAvailable(long id)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT 1 FROM properties WHERE property_id=? AND status='AVAILABLE'")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next();}}}
}
